import{_ as t,o,c as _,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/94-为何非安全型人群很难采取有效沟通？.md","filePath":"books/attached/94-为何非安全型人群很难采取有效沟通？.md","lastUpdated":1794316978000}'),r={name:"books/attached/94-为何非安全型人群很难采取有效沟通？.md"};function n(d,a,c,l,i,p){return o(),_("div",null,[...a[0]||(a[0]=[e("h3",{id:"为何非安全型人群很难采取有效沟通",tabindex:"-1"},[s("为何非安全型人群很难采取有效沟通？ "),e("a",{class:"header-anchor",href:"#为何非安全型人群很难采取有效沟通","aria-label":'Permalink to "为何非安全型人群很难采取有效沟通？"'},"​")],-1),e("p",null,"有效沟通看起来不用费什么脑子，毕竟世上无难事，只怕有心人不是吗？的确没错，但有效沟通的轻而易举，仅仅是针对安全型依恋风格的。非安全型人群往往并不知道自己的问题真正出在哪里。从而他们会将积蓄已久的情绪突然爆发出来。而研究显示，安全型人群就不会反应如此强烈，也不容易情绪过激，因此就可以比较从容地进行有效沟通，同时还能考虑到对方的感受。安全型人群本就相信自己是值得被爱、值得被倾注感情的，因此也希望自己的伴侣能变得活跃而体贴。基于这种信念，他们就不容易被消极情绪所左右，他们很容易保持镇定、重整旗鼓、并且相信对方会产生积极回应。而这种态度是可以影响到别人的。来自加州大学圣塔芭芭拉分校的南希·柯林斯（Nancy Collins）的主要研究方向就包括构成成人亲密关系的社会与认知过程，以及这些过程对于健康和积极情绪的影响。而来自南加州大学的斯蒂芬·里德（Stephen Read）则专门研究社会推理和社会行为的神经网络模型。两人共同研究发现，安全型依恋风格的人群，往往担任着有效沟通导师的角色，他们很擅长引导他人敞开心扉，并且吐露自己的心声。但是对于非安全型的人来说，事情又会如何呢？",-1)])])}const f=t(r,[["render",n]]);export{m as __pageData,f as default};
